60	export function parseArgs(argv) {
61	  const args = {};
62	  for (let n = 0; n < argv.length; n += 1) {
63	    const m = /^--([a-z-]+)$/.exec(argv[n]);
64	    if (m) { args[m[1]] = argv[n + 1] ?? ''; n += 1; }
65	  }
66	  const issue = Number(args.issue);
67	  if (!Number.isInteger(issue) || issue <= 0) return { error: '--issue must be the work item\'s issue number' };
68	  if (!OUTCOMES[args.outcome]) {
69	    return { error: `--outcome must be one of ${Object.keys(OUTCOMES).join(', ')}, got ${JSON.stringify(args.outcome ?? null)}` };
70	  }
71	  if (!String(args.summary ?? '').trim()) return { error: '--summary must say what happened; it is the item\'s only durable account' };
72	  if (args.outcome === 'approval' && !args.pr) {
73	    return { error: '--pr must name the pull request an approval park is waiting on — a park nobody can act on is not a park' };
74	  }
75	  return {
76	    issue, outcome: args.outcome, summary: args.summary, pr: args.pr ? Number(args.pr) : null,
77	    repo: args.repo || null, itemFile: args['item-file'] || null,
78	  };
79	}
80	
81	// Why an item may NOT be converged by this call. Refusing loudly beats writing a
82	// terminal state onto the wrong issue: this runs from a session, whose whole
83	// notion of which item it holds came from an untrusted fire payload.
84	export function refusal(item, issue) {
85	  if (!item) return `#${issue} could not be read`;
86	  // A marked issue IS its own item, so the title test cannot be the
87	  // membership test: what says this is one is the machine block adoption
88	  // wrote — never the body's first line, which on a marked issue is a person's prose.
89	  //
90	  // THREE SIGNALS, ANY ONE SUFFICIENT. A membership test gated on the single artifact
91	  // it exists to validate refuses exactly the items that artifact is missing from: an
92	  // issue adopted before the block delimiters existed carries its fields bare, and
93	  // refusing it forces a by-hand convergence that drops half the transition. The
94	  // origin label is the independent one - carried for
95	  // life, and platform-write-gated like the block was.
96	  const marked = ORIGIN_LABELS.some((name) => hasLabel(item, name));
97	  if (!parseWorkItemTitle(item.title ?? '') && machineBlockOf(item.body ?? '') === null && !marked) {
98	    return `#${issue} is not a Claudinite work item`;
99	  }
100	  if (item.state !== 'open') return `#${issue} is already closed — it was converged once already`;
101	  if (!isStatus(item, STATUS_RUNNING_AGENT)) {
102	    return `#${issue} is not with an agent (\`${STATUS_RUNNING_AGENT}\`) — this session does not hold it, so it is not this session's to converge`;
103	  }
104	  return null;
105	}
106	
107	// The record line for this item, or null where the vocabulary has no true answer.
108	export const recordLine = (item, status) => {
109	  const parsed = parseWorkItemTitle(item.title);
110	  return status && parsed
111	    ? renderTaskExec({ pack: parsed.pack, task: parsed.task, slotId: `#${item.number}`, status })
112	    : null;
113	};
114	
115	// The comment one converge writes: the session's account, then the record, so a
116	// reader and a parser both find what they came for in one place.
117	// THE EPISODE ENDS WHERE THE ITEM IS LET GO OF (F18/F24). An executor that parks
118	// an item strikes its own claim on the way out; a SESSION cannot — its claim is
119	// the executor's, and it has no edit for it — so the boundary rides its own
120	// comment instead. `claimWinner` reads the last comment carrying the marker
121	// whatever wrote it, so this is the same mechanism, not a second one.
122	//
123	// Without it every claim from the parked episode outlives the park: a person
124	// re-queues the item, the next executor claims it, and `claimWinner` hands the
125	// episode to the dead claim that is still the earliest one on the issue. The item
126	// then loses every race it will ever have — which is the livelock F18 describes,
127	// reached through the one converge that had no way to say it had let go.
128	export function convergeComment(item, { summary, pr, record, boundary = false }) {
129	  const rec = recordLine(item, record);
130	  const line = rec ? `\n\n\`\`\`\n${rec}\n\`\`\`` : '';
131	  const waiting = pr ? `\n\nWaiting on a person: merge or close #${pr}, then close this item.` : '';
132	  const ends = boundary
133	    ? `\n\n${EPISODE_MARKER}\nThis session released the item without closing it; every claim before this line is spent.`
134	    : '';
135	  return `${summary.trim()}${waiting}${line}${ends}`;
136	}
137	
138	// THE TRANSITION AS DATA (#1374). The sessions agentic work is handed to have no
139	// REST route to their own repository, so the sequence is planned as OPS and
140	// executed by whoever can. The planner is
141	// the single source of what a convergence IS; the executors differ only in
142	// transport. The session still supplies nothing but the judgment.
143	//
144	// Removes are granular and unconditional — every spelling of the status being
145	// left, not only the ones this snapshot shows: a member's items outlive its
146	// converges, so an item may wear an older engine's spelling.
147	export function convergeOps(item, plan) {
148	  const spec = OUTCOMES[plan.outcome];
149	  // A park leaves the item open for somebody else to claim, so its comment carries
150	  // the episode boundary; a close needs none — nothing re-claims a closed item.
151	  const ops = [{ kind: 'comment', issue: item.number, body: convergeComment(item, { ...plan, record: spec.record, boundary: !spec.closes }) }];
152	
153	  // The record goes to BOTH sinks, and neither is redundant: the comment above is
154	  // the durable one (Actions logs expire, the item does not), while this printed
155	  // copy lands in the session transcript, which is what the usage fold reads for
156	  // the task-status census.
157	  const rec = recordLine(item, spec.record);
158	  if (rec) ops.push({ kind: 'record', line: rec });
159	
160	  for (const label of spellingsOf(STATUS_RUNNING_AGENT)) {
161	    ops.push({ kind: 'removeLabel', issue: item.number, name: label });
162	  }
163	  // ONE label, on both paths: the outcome IS the status. A park in particular is
164	  // never a pair, so nothing can be half-applied (#1385).
165	  ops.push({ kind: 'addLabel', issue: item.number, name: spec.label });
166	
167	  // THE PARK'S END CONDITION (#1468). The comment above already tells a person to
168	  // merge or close the pull request; this says the same thing where the repair phase can
169	  // read it, so the item ends when that happens instead of waiting for someone to
170	  // notice it already did. Every park that names one gets it, not only `approval`.
171	  if (!spec.closes && plan.pr) {
172	    ops.push({ kind: 'setBody', issue: item.number, body: editItemBody(item.body, (m) => withEndsWhen(m, plan.pr)) });
173	  }
174	
175	  // SUPERSEDING. The executor decided at resolution which of this
176	  // task's earlier pull requests a `supersede_existing_pr` run replaces and stamped
177	  // them on the item; they close only once THIS run's own pull request exists — a
178	  // run that delivered nothing, or broke, leaves them where they were, so a review
179	  // member's pending pull request is never taken away for nothing.
180	  const { supersedes } = parseWorkItemBody(item.body ?? '');
181	  if (plan.pr && (plan.outcome === 'done' || plan.outcome === 'approval')) {
182	    for (const number of supersedes) {
183	      ops.push({ kind: 'closePull', number, successor: plan.pr, body: `Superseded by #${plan.pr}, a later run of the same task. Closing this one.` });
184	    }
185	  }
186	
187	  if (spec.closes) {
188	    // A DONE TERMINAL CLOSES THE ISSUE IT STANDS ON, marked or filed (#1489).
189	    // `done` is the one outcome
190	    // that means nothing is left for anyone to act on, so an issue left open under
191	    // it asks its author to come and agree with what the run already settled. Every
192	    // other outcome parks, and a park leaves the issue open to be waited on.
193	    ops.push({ kind: 'close', issue: item.number, stateReason: spec.stateReason });
194	    return ops;
195	  }
196	
197	  // A REQUEST ITEM WRITES BACK TO ITS ISSUE, on the one end that is its business.
198	  // Only the approval park: a failure deliberately writes nothing and
199	  // leaves `claude-queued` standing, because re-arming work that writes code is a
200	  // person's decision and that standing label is what stops the next scheduler run
201	  // queueing a second run of the same request. Only a LEGACY shadow item writes
202	  // back to a different issue.
203	  const { request } = parseWorkItemBody(item.body ?? '');
204	  if (request && request !== item.number && plan.outcome === 'approval') {
205	    ops.push({ kind: 'comment', issue: request, body: `A pull request for this is open and waiting on you: #${plan.pr}. Merge or close it.` });
206	    ops.push({ kind: 'removeLabel', issue: request, name: QUEUED_LABEL });
207	    ops.push({ kind: 'addLabel', issue: request, name: IN_REVIEW_LABEL });
208	  }
209	  return ops;
210	}
211	
212	// THE SESSION EXECUTOR'S SCRIPT. Same ops, addressed to the GitHub tools a session
213	// does have. Two differences forced by that surface, both handled here rather than
214	// left to the session to work out:
215	//
216	//  - THERE IS NO GRANULAR LABEL WRITE. `issue_write` replaces the whole set, so the
217	//    granular removes and adds are folded into the FINAL set here, computed from the
218	//    labels this item was read with. Everything not a status label is carried through.
219	//  - THE RECORD IS PRINTED BY THE SESSION, which is where it has to be anyway: the
220	//    usage fold reads the census out of the session transcript.
221	export function sessionScript(item, plan, repo) {
222	  const [owner, name] = String(repo).split('/');
223	  const lines = [];
224	  let n = 0;
225	  const step = (s) => { n += 1; lines.push(`${n}. ${s}`); };
226	
227	  // The item's own label set can be computed exactly, because the item was read
228	  // with its labels. Any OTHER issue's cannot — so that one is emitted as a
229	  // read-modify-write naming only the change, and never as a computed set, which
230	  // would silently drop every label this process never saw.
231	  const own = new Set(labelNames(item));
232	  const foreign = [];
233	  // The body write folds into the item's own `issue_write`, which is one call
234	  // either way. A park never closes, so the step it folds into is the trailing
235	  // label write below.
236	  let newBody = null;
237	
238	  for (const op of convergeOps(item, plan)) {
239	    if (op.kind === 'comment') {
240	      step(`\`add_issue_comment\` — owner \`${owner}\`, repo \`${name}\`, issue_number \`${op.issue}\`, body exactly:\n\n<<<BODY\n${op.body}\n>>>END\n`);
241	    } else if (op.kind === 'record') {
242	      step(`Output this line, on its own, in your reply. Nothing else emits it, and the usage census is read from your transcript:\n\n    ${op.line}\n`);
243	    } else if (op.kind === 'removeLabel' || op.kind === 'addLabel') {
244	      if (op.issue === item.number) {
245	        if (op.kind === 'removeLabel') own.delete(op.name); else own.add(op.name);
246	      } else {
247	        foreign.push(op);
248	      }
249	    } else if (op.kind === 'setBody' && op.issue === item.number) {
250	      newBody = op.body;
251	    } else if (op.kind === 'close') {
252	      step(`\`issue_write\` — method \`update\`, owner \`${owner}\`, repo \`${name}\`, issue_number \`${op.issue}\`,`
253	        + ` labels \`${JSON.stringify([...own])}\`, state \`closed\`, state_reason \`${op.stateReason}\``);
254	      own.clear();
255	    } else if (op.kind === 'closePull') {
256	      step(`\`add_issue_comment\` — owner \`${owner}\`, repo \`${name}\`, issue_number \`${op.number}\` (a pull request), body exactly:\n\n<<<BODY\n${op.body}\n>>>END\n`);
257	      step(`\`update_pull_request\` — owner \`${owner}\`, repo \`${name}\`, pullNumber \`${op.number}\`, state \`closed\``);
258	    }
259	  }
260	  // A park never closed, so its label write is still owed.
261	  if (own.size) {
262	    step(`\`issue_write\` — method \`update\`, owner \`${owner}\`, repo \`${name}\`, issue_number \`${item.number}\`,`
263	      + ` labels \`${JSON.stringify([...own])}\``
264	      + (newBody === null ? '' : `, body exactly:\n\n<<<BODY\n${newBody}\n>>>END\n`));
265	  }
266	  for (const op of foreign) {
267	    step(`On #${op.issue}: ${op.kind === 'addLabel' ? 'ADD' : 'REMOVE'} the label \`${op.name}\`.`
268	      + ` Read that issue's current labels first and write them back with only this one change —`
269	      + ` \`issue_write\` replaces the whole set, and this process never saw the rest.`);
270	  }
271	  return lines.join('\n');
272	}
273	
274	async function main() {
275	  const plan = parseArgs(process.argv.slice(2));
276	  if (plan.error) {
277	    console.error(`converge-item: ${plan.error}`);
278	    process.exitCode = 2;
279	    return;
280	  }
281	
282	  // The repo this item lives in. `--repo` is what the session's instructions pass; the two
283	  // environment names answer for a session whose harness sets one of them.
284	  const repo = plan.repo ?? actionsEnv().CLAUDINITE_ITEM_REPO ?? actionsEnv().GITHUB_REPOSITORY ?? null;
285	  if (!repo) {
286	    console.error('converge-item: --repo <owner/name> names the repository this item lives in');
287	    process.exitCode = 2;
288	    return;
289	  }
290	
291	  // THE ITEM IS HANDED IN. This process cannot read it — that is the whole premise
292	  // of the file — so the session reads it with its own tools and passes it through.
293	  // A file rather than an argument: an item's body is prose of arbitrary length, and
294	  // a shell-quoted one is a quoting bug waiting for the first apostrophe.
295	  // `CLAUDINITE_ITEM_JSON` stays readable for a member whose session instructions are
296	  // a cycle behind, since a mount updates on its own schedule.
297	  const raw = plan.itemFile
298	    ? await readFile(plan.itemFile, 'utf8')
299	    : (actionsEnv().CLAUDINITE_ITEM_JSON ?? '');
300	  let item = null;
301	  try { item = JSON.parse(raw || 'null'); } catch { item = null; }
302	  if (!item) {
303	    console.error('converge-item: --item-file must hold the issue as your GitHub tools returned it'
304	      + ' (number, title, body, state, labels).\n'
305	      + `Read it first: \`issue_read\` method \`get\` on ${repo} #${plan.issue}, save the JSON, pass the path.`);
306	    process.exitCode = 2;
307	    return;
308	  }
309	
310	  const no = refusal(item, plan.issue);
311	  if (no) { console.error(`converge-item: ${no}`); process.exitCode = 1; return; }
312	
313	  // The successful outcome. Everything below is the transition, decided here and
314	  // performed by the session — so it goes to stdout and the process exits clean.
315	  console.log('converge-item: the transition below is yours to execute.\n'
316	    + 'Make these calls with your GitHub tools, in this order, changing nothing. Then stop.\n');
317	  console.log(sessionScript(item, plan, repo));
318	}
319	
320	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
321	  main().catch((e) => { console.error(e); process.exitCode = 1; });
322	}
